import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.6vsupRmR.js";const s="/arkel-site/assets/arkel-architecture.drawio.BGvbsy51.png",u=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/overview.md","filePath":"architecture/overview.md"}'),d={name:"architecture/overview.md"};function i(n,e,l,c,h,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>An Arkel deployment has three kinds of participants:</p><ul><li><strong>Clients</strong> encrypt and erasure-code objects locally.</li><li><strong>Index nodes</strong> form a Raft cluster that owns the global metadata.</li><li><strong>Storage nodes</strong> hold encrypted shards that store data.</li></ul><p><img src="'+s+'" alt="Arkel architecture"></p><h2 id="participants" tabindex="-1">Participants <a class="header-anchor" href="#participants" aria-label="Permalink to &quot;Participants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Command</th><th>Holds</th><th>Responsibilities</th></tr></thead><tbody><tr><td>Client</td><td><code>arkel client</code></td><td>Master key, plaintext</td><td>Encrypt, erasure-code, build &amp; sign manifests, fetch shards</td></tr><tr><td>Index node</td><td><code>arkel index</code></td><td>Raft log + SQLite state</td><td>Catalog, ownership, quotas, node registry</td></tr><tr><td>Storage node</td><td><code>arkel storage</code></td><td>Encrypted shard blobs</td><td>Register, store, serve, garbage-collect</td></tr></tbody></table><h2 id="write-path" tabindex="-1">Write path <a class="header-anchor" href="#write-path" aria-label="Permalink to &quot;Write path&quot;">​</a></h2><ol><li>The client picks storage targets from the healthy-node list and chooses an erasure configuration (<code>k</code> data + <code>m</code> parity shards; default <strong>8 + 6</strong>).</li><li>The object is <strong>encrypted on the client</strong> with XChaCha20-Poly1305, using a per-object key derived via HKDF-SHA256 from the master key.</li><li>The ciphertext is <strong>erasure-coded</strong> into <code>k + m</code> shards.</li><li>The client hosts the shards locally and each storage node <strong>pulls</strong> its assigned shard over QUIC. Shards are content-addressed by BLAKE3.</li><li>The client builds a <strong>manifest</strong> (object hash, sizes, shard placements), signs it, and commits it to the index cluster via Raft.</li></ol><p>Because encryption happens before coding, every storage node only ever holds a slice of ciphertext.</p><h2 id="read-path" tabindex="-1">Read path <a class="header-anchor" href="#read-path" aria-label="Permalink to &quot;Read path&quot;">​</a></h2><ol><li>The client reads the manifest from the index cluster (owner-gated).</li><li>It fetches the <code>k</code> data shards in parallel, substituting parity shards if any are missing, and reconstructs the ciphertext.</li><li>It decrypts once and verifies the plaintext against the manifest&#39;s BLAKE3 object hash. A corrupted or malicious shard fails the check.</li></ol><p>Reads only need <code>k</code> of the <code>k + m</code> shards, so the object survives losing up to <code>m</code> nodes.</p><h2 id="the-index-cluster" tabindex="-1">The index cluster <a class="header-anchor" href="#the-index-cluster" aria-label="Permalink to &quot;The index cluster&quot;">​</a></h2><p>The metadata — buckets, objects, ownership, quotas, and the storage-node registry — is a replicated state machine built on <strong>OpenRaft</strong>. Every write (manifest commit, quota credit, node registration) is a log entry committed to a quorum of index nodes and applied deterministically to each node&#39;s SQLite state.</p><p>Reads are served under a <strong>leader lease</strong> and metadata is kept linearizable.</p><h2 id="storage-nodes" tabindex="-1">Storage nodes <a class="header-anchor" href="#storage-nodes" aria-label="Permalink to &quot;Storage nodes&quot;">​</a></h2><p>Storage nodes hold shards as content-addressed blobs in an iroh-blobs store. They register their advertised address and capacity with the index, send heartbeats, and run a background <strong>Garbage collection loop</strong> to clean up dead references.</p><h2 id="background-work" tabindex="-1">Background work <a class="header-anchor" href="#background-work" aria-label="Permalink to &quot;Background work&quot;">​</a></h2><ul><li><strong>Repair</strong> — a standalone, idempotent <code>arkel repair</code> pass finds objects below their target <code>k</code>/<code>m</code> and re-encodes and redistributes shards.</li><li><strong>Garbage collection</strong> — storage nodes delete unreferenced shards on an interval; the index authorizes deletions scoped to the node&#39;s own placements.</li><li><strong>Contribution grants</strong> — the index periodically credits operators for the bytes they host, subject to an online grace period.</li></ul>',19)])])}const b=t(d,[["render",i]]);export{u as __pageData,b as default};
